<?php
namespace App\Http\Controllers\Dashboard;
use App\Http\Controllers\Controller; use App\Http\Controllers\Dashboard\Concerns\RedirectsAfterSave; use Illuminate\Http\Request;
class MotorcycleController extends Controller { use RedirectsAfterSave; public function edit(Request $request) { $registration=$request->user()->registrations()->with('package','motorcycle')->latest()->firstOrFail(); abort_unless($request->user()->can('view',$registration),403); return view('dashboard.motorcycle', compact('registration')); } public function update(Request $request) { $registration=$request->user()->registrations()->with('package')->latest()->firstOrFail(); abort_if(! $registration->requiresMotorcycle(), 404); $data=$request->validate(['brand'=>['required','string','max:255'],'model'=>['required','string','max:255'],'year'=>['nullable','integer','between:1900,2100'],'license_plate'=>['nullable','string','max:255'],'vin'=>['nullable','string','max:255'],'front_tire_size'=>['nullable','string','max:255'],'rear_tire_size'=>['nullable','string','max:255'],'notes'=>['nullable','string'],'return_to'=>['nullable','url']]); $returnTo=$data['return_to']??null; unset($data['return_to']); $registration->motorcycle()->updateOrCreate(['registration_id'=>$registration->id],$data+['user_id'=>$request->user()->id]); if ($returnTo) $request->merge(['return_to'=>$returnTo]); return $this->redirectAfterSave($request,'Motorcycle saved'); } }
